exercises.solution:
function rollDice(count, sides) {
  count = count || 1;
  sides = sides || 6;
  const rolls = [];
  for (let i = 0; i < count; i++) {
    rolls.push(Math.floor(Math.random() * sides) + 1);
  }
  const total = rolls.reduce((sum, r) => sum + r, 0);
  return { rolls, total };
}

